 execute 'set local role authenticated';
 begin perform public.admin_save_pv_document('{}',null);raise exception 'Nonadmin source write allowed';exception when others then if sqlerrm<>'Admin access required' then raise;end if;end;
 begin perform public.capture_pv_document('synthetic-fda',now(),null,'{}','[]');raise exception 'Client collector call allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email','pipeline-admin@example.invalid','role','authenticated')::text,true);
 d:=public.admin_save_pv_document('{"id":"synthetic-fda","title":"Synthetic regulatory source","country":"US","agency":"FDA","url":"https://www.fda.gov/synthetic","edition":"Synthetic edition","topic":"PV quality","lifecycle":"Both","norm":"Guidance","legal_basis":"Synthetic legal basis","applicability":"Synthetic organizational scope","source_status":"current","published_on":"","effective_on":"","status":"active","capture_note":"Synthetic test setup"}',null);
