 execute 'reset role';
 cap:=jsonb_build_object('original_hash',repeat('a',64),'content_hash',repeat('b',64),'source_url',d.url,'content_kind','html','partial',false,'excluded',0,'archive_path',d.id||'/'||repeat('a',64)||'.html');
 items:=jsonb_build_array(jsonb_build_object('anchor','paragraph-1','statement','The sponsor must maintain documented safety procedures.','context','Confirm the regulated scope and exceptions.','fingerprint',repeat('c',64),'classification','baseline'));
