 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email','pipeline-admin@example.invalid','role','authenticated')::text,true);
 begin perform public.admin_review_pv_candidate(cand.id,'accepted','Synthetic wrong citation','SYNTHETIC-PIPE',null,body||'{"source_url":"https://www.fda.gov/different"}');raise exception 'Citation changed';exception when others then if sqlerrm<>'Keep the captured document citation pinned' then raise;end if;end;
