 cas:=public.advance_company_case(cas.id,cas.version,'decide','{"decision":"relevant","reason":"Synthetic applicable product and scope"}');
 draft:=public.save_pv_impact_requirement(cas.id,'business','{"statement":"Document the approved organizational safety control","acceptance_criteria":"Approved scope is traceable to the source","rationale":"Synthetic control gap","system_scope":"Synthetic configuration"}',null);
 begin perform public.save_pv_impact_requirement(cas.id,'business','{"statement":"Concurrent draft","acceptance_criteria":"Criteria","rationale":"Reason","system_scope":""}',null);raise exception 'Concurrent draft accepted';exception when others then if sqlerrm<>'Draft changed. Reload before saving' then raise;end if;end;
 draft:=public.review_pv_impact_requirement(draft.id,'submit','Synthetic review requested',null);draft:=public.review_pv_impact_requirement(draft.id,'approve','Synthetic personal self-review',null);
 if draft.status<>'approved' then raise exception 'Personal draft review failed';end if;
