 cas:=public.open_company_case('synthetic-team-pipeline',null,t);cas:=public.advance_company_case(cas.id,cas.version,'decide','{"decision":"relevant","reason":"Synthetic applicable team scope"}');
 draft:=public.save_pv_impact_requirement(cas.id,'system','{"statement":"Validate the configured safety reporting behavior","acceptance_criteria":"Synthetic tests pass approved regional validation","rationale":"Synthetic interface impact","system_scope":"Argus synthetic configuration"}',null);
 begin perform public.review_pv_impact_requirement(draft.id,'submit','Synthetic self-review attempt','pipeline-admin@example.invalid');raise exception 'Team self-review allowed';exception when others then if sqlerrm not like 'Choose a different%' then raise;end if;end;
 draft:=public.review_pv_impact_requirement(draft.id,'submit','Synthetic independent review requested','pipeline-reviewer@example.invalid');
 begin perform public.review_pv_impact_requirement(draft.id,'approve','Author approval attempt',null);raise exception 'Author approved';exception when others then if sqlerrm not like 'Only the designated%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'email','pipeline-outsider@example.invalid','role','authenticated')::text,true);
 select count(*) into n from public.pv_impact_requirements where case_id=cas.id;if n<>0 then raise exception 'Draft leaked outside team';end if;
 begin perform public.review_pv_impact_requirement(draft.id,'approve','Outsider attempt',null);raise exception 'Outsider review allowed';exception when others then if sqlerrm<>'Case access denied' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'email','pipeline-reviewer@example.invalid','role','authenticated')::text,true);
