 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email','pipeline-admin@example.invalid','role','authenticated')::text,true);
 otherdraft:=public.save_pv_impact_requirement(cas.id,'data','{"statement":"Validate approved data definitions","acceptance_criteria":"Synthetic field mappings pass validation","rationale":"Synthetic terminology impact","system_scope":"Synthetic regional profile"}',null);
